							data: [null,{type:"data",data:{tool:{name:"Iristick.H1",slug:"Iristick.H1",sold_out:true,shop_url:"",url:"https://iristick.com/tools/Iristick.H1/",meta_title:"Iristick.H1 – Heavy-Duty Smart Glasses (Sold Out) | Iristick",meta_description:"Rugged smart glasses for heavy-duty work, with helmet or headband mounting, dual central camera, optical zoom and barcode scanner. No longer available to order.",label:"",showcase_image_url:"/_app/immutable/assets/h1-side-header-4k.B5v0vbum.webp",showcase_seo_image_url:"https://iristick.com/pictures/Iristick.H1.webp",showcase_video_url:"/_app/immutable/assets/website-header-h1-h264.B_hsy1Mk.mp4",short_description:"Rugged, high-performance smart glasses built for heavy-duty use, seamlessly integrating into your PPE with helmet or headband mounting options. Designed for both right- and left-eye dominance. Featuring a dual central camera, powerful optical zoom lens, and integrated barcode scanner, they enable hands-free operation and real-time information sharing in demanding environments.",price:"2275",pricing_text:"Built for heavy-duty environments. It offers robust construction to withstand challenging conditions, ensuring reliable performance in the field.",addtional_info:[{name:"Key Features",tag:"features",topics:[{icon:"camera",title:"Dual central camera & optical zoom",description:"Capture High-quality images and videos from a natural viewpoint with optical zoom for precise detail.",file:""},{icon:"record_voice_over",title:"Hands-free control",description:"Use the touchpad or voice commands for seamless, hands-free operation.",file:""},{icon:"shield",title:"Robust yet comfortable",description:"These smart safety glasses are designed to endure tough environments while providing all-day comfort.",file:""},{icon:"battery_6_bar",title:"Full-shift battery",description:"The long lasting battery is built to keep you going through a full workday.",file:""},{icon:"fit_screen",title:"Optimized display",description:"See additional information without obstructing your natural field of view. The Iristick.H1 has an OLED display, offering crisp contrast.",file:""},{icon:"head_mounted_device",title:"Head mounted",description:"High-end head-mounted smart glasses. Can be clipped onto customised or personal PPE or headbands.",file:""}]},{name:"Thoughtful Additions",tag:"additions",topics:[{icon:"scale",title:"180 grams",description:"Barely there, fully capable.Experience unparalleled comfort with the Iristick.H1 smart glasses, weighing just 180 grams. By offloading processing and battery functions to your smartphone, we've minimized on-head weight and eliminated heat and radiation near your temples. This design ensures all-day wearability without discomfort, allowing you to focus entirely on your tasks.",file:""},{icon:"cable",title:"Smartphone-powered",description:"The Iristick.H1 connects via cable to iOS and Android smartphones, using their cellular and Wi-Fi connectivity while serving as the hub for app installation. This design maximizes performance and battery life by offloading processing to the smartphone. For IT teams, the glasses function as an accessory, seamlessly integrating with existing managed mobile devices.",file:""},{icon:"eyeglasses",title:"Left or right eye display",description:"The Iristick.H1 smart glasses are designed for both right- and left-eye dominant users. Thanks to their 180° flip capability, the display can be worn on either eye without compromising functionality. They fit comfortably over prescription or safety glasses, ensuring seamless integration into any PPE setup. This flexibility makes them a universal tool for any workforce.",file:""},{icon:"disabled_visible",title:"Privacy light",description:"The Iristick.H1 feature a built-in privacy light that activates whenever the cameras are recording. This ensures bystanders are always aware when filming is in progress, providing an extra layer of transparency and privacy protection.",file:""},{icon:"zoom_in_map",title:"Aimable zoom camera",description:"The Iristick.H1 feature a manually adjustable optical zoom camera, allowing precise control over what you capture. A built-in laser displays a red dot, indicating the exact center of the zoom camera’s field of view. This ensures accurate aiming for detailed inspections, documentation, and remote support.",file:""}]},{name:"Documents",tag:"documents",topics:[{icon:"file_save",title:"spec-sheet-iristick-h1.pdf",description:"",file:"/_app/immutable/assets/spec-sheet-iristick-h1.CgDSlgGY.pdf"}]}]},faq:[{tool:["Iristick.H1"],title:"What's in the Box?",description:"The Iristick.H1 package includes smart glasses, a pocket unit (Android or iOS), a battery charger, a USB-C cable, a magnetic plate, a protective case and an Iristick headband or helmet."},{tool:["Iristick.H1"],title:"Using the smart glasses",description:"Connect the smart glasses to the pocket unit via the provided coax cable. The pocket unit then connects to your smartphone via USB-C or lightning if it's an older iPhone, utilizing the phone’s processing power for optimal performance."},{tool:["Iristick.H1"],title:"Charging",description:"Charge the pocket unit using the included charger and USB-C cable. A full charge takes about 2 hours. Hot-swapping batteries allows continuous operation."},{tool:["Iristick.H1"],title:"Why is it cabled?",description:"The cabled design ensures high performance and extended battery life by offloading processing to the smartphone. This also reduces heat, weight and radiation near the head."},{tool:["Iristick.H1"],title:"Left eye and right eye compatibility",description:"The Iristick.H1 features an adjustable display for both left and right eye dominance, ensuring optimal usability for all users."},{tool:["Iristick.H1"],title:"What if I'm wearing prescription glasses?",description:"The Iristick.H1 can be used in combination with existing prescription glasses, allowing seamless integration with personal eyewear."},{tool:["Iristick.H1"],title:"What if I'm wearing PPE?",description:"The Iristick.H1 is designed for easy attachment to PPE such as helmets and headbands, ensuring safety compliance while using the device."}]},uses:{params:["slug"]}}],
